event-driven-programming.pseudocode:
handlers = {}  # 이벤트 종류 -> 콜백 목록

def on(event_type, callback):
    # 핸들러 등록 (옵저버 패턴과 동일)
    handlers.setdefault(event_type, []).append(callback)

def run_loop(queue, wait_for_event):
    while True:
        if not queue:
            wait_for_event(queue)  # 입력·메시지 도착까지 대기
            continue
        etype, data = queue.pop(0)
        if etype == 'quit':
            break
        for cb in handlers.get(etype, []):
            cb(data)  # 핸들러는 짧게, 긴 작업은 위임

event-loop.pseudocode:
def event_loop(selector, timers):
    while True:
        # 가장 가까운 타이머 만료까지만 대기
        timeout = timers.next_timeout()
        events = selector.wait(timeout)  # I/O 준비 통지
        for fd, mask in events:
            handler = selector.handler_of(fd)
            handler(fd, mask)  # 논블로킹 콜백 실행
        for callback in timers.pop_expired():
            callback()  # 만료 타이머 처리
        # 콜백이 블로킹되면 모든 연결 처리가 멈춤

event-sourcing.pseudocode:
def apply(state, ev):
    # 이벤트 하나를 상태에 반영 (부수효과 없음)
    if ev['type'] == 'Opened':
        return 0
    if ev['type'] == 'Deposited':
        return state + ev['amount']
    if ev['type'] == 'Withdrawn':
        return state - ev['amount']
    return state

def load(log, snapshot=None):
    # 스냅샷 (상태, seq)가 있으면 그 이후 이벤트만 재생
    state, since = snapshot if snapshot else (None, 0)
    for ev in log:
        if ev['seq'] > since:
            state = apply(state, ev)
    return state

def withdraw(log, amount):
    balance = load(log)
    if balance < amount:
        raise ValueError('잔액 부족')
    # 기존 상태를 고치지 않고 새 이벤트를 추가만 함
    log.append({'seq': len(log) + 1, 'type': 'Withdrawn',
                'amount': amount})
